setOpen.runtimeFunction:
(amount = 0) => {
    const open = THREE.MathUtils.clamp(Number(amount) || 0, 0, 1);
    doors[0].rotation.z = 0.92 * open;
    doors[1].rotation.z = -0.92 * open;
    cavity.visible = open > 0.01;
    bellyHatch.userData.open = open;
  }

